ALTER TABLE "domain_events" ADD CONSTRAINT "domain_events_company_kind_check" CHECK (("domain_events"."company_id" IS NULL OR ("domain_events"."task_id" IS NULL AND (("domain_events"."kind" IN ('knowledge.record_changed','specialist.assignment_changed') AND "domain_events"."run_id" IS NULL) OR ("domain_events"."kind" IN ('run.done','run.failed','run.crashed','run.abandoned','run.needs_input','run.operational_attention_acknowledged','run.operational_cleanup_changed') AND "domain_events"."run_id" IS NOT NULL)))) IS TRUE);